//! Raw FFI over the vendored libvpx (VP8 + VP9), generated by build.rs against the headers of the libvpx
//! revision Chrome pins. Linked by the DEFAULT build -- korvus-render's VP9/VP8 `<video>` decoders (D144) --
//! and by korvus-runtime's `webrtc-media` feature (the VP8 send encoder).
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code)]
include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

#[cfg(test)]
mod tests {
    use super::*;
    use std::os::raw::{c_int, c_uint, c_ulong};

    /// Drain every frame packet the encoder has ready into `out` (the compressed bytes).
    ///
    /// SAFETY: `ctx` is a live encoder; each packet's buffer is valid only until the next libvpx call, so
    /// it is copied here. `VPX_CODEC_CX_FRAME_PKT == 0`; the union's `.frame` is valid only for that kind.
    unsafe fn drain_cx(ctx: *mut vpx_codec_ctx_t, out: &mut Vec<u8>) {
        let mut iter: vpx_codec_iter_t = std::ptr::null();
        loop {
            let pkt = vpx_codec_get_cx_data(ctx, &mut iter);
            if pkt.is_null() {
                break;
            }
            if (*pkt).kind == 0 {
                let f = (*pkt).data.frame;
                out.extend_from_slice(std::slice::from_raw_parts(f.buf as *const u8, f.sz));
            }
        }
    }

    /// Encode a solid 16x16 gray keyframe with `cx` and decode it with `dx`; returns the decoded
    /// `(width, height)` and the first luma byte. Exercises the full encode + decode link for one codec.
    ///
    /// SAFETY: a self-contained encode→decode of a stack image; every context is destroyed before return.
    unsafe fn round_trip(cx: *const vpx_codec_iface_t, dx: *const vpx_codec_iface_t) -> (u32, u32, u8) {
        assert!(!cx.is_null() && !dx.is_null(), "libvpx built without this codec");
        let (w, h) = (16usize, 16usize);

        // ---- encode ----
        let mut cfg: vpx_codec_enc_cfg_t = std::mem::zeroed();
        assert_eq!(vpx_codec_enc_config_default(cx, &mut cfg, 0), vpx_codec_err_t_VPX_CODEC_OK);
        cfg.g_w = w as c_uint;
        cfg.g_h = h as c_uint;
        cfg.g_timebase.num = 1;
        cfg.g_timebase.den = 30;
        cfg.rc_target_bitrate = 200;
        cfg.g_pass = vpx_enc_pass_VPX_RC_ONE_PASS;
        cfg.g_lag_in_frames = 0;
        cfg.g_error_resilient = VPX_ERROR_RESILIENT_DEFAULT;
        cfg.g_threads = 1;

        let mut ectx: vpx_codec_ctx_t = std::mem::zeroed();
        assert_eq!(
            vpx_codec_enc_init_ver(&mut ectx, cx, &cfg, 0, VPX_ENCODER_ABI_VERSION as c_int),
            vpx_codec_err_t_VPX_CODEC_OK
        );

        // All I420 planes gray (0x80): the whole staging buffer is set, so every plane reads 128 whatever
        // strides vpx_img_wrap picks. w*h*2 is ample for I420 (3*w*h/2) plus any padding.
        let mut buf = vec![128u8; w * h * 2];
        let mut img: vpx_image_t = std::mem::zeroed();
        assert!(
            !vpx_img_wrap(&mut img, vpx_img_fmt_VPX_IMG_FMT_I420, w as c_uint, h as c_uint, 1, buf.as_mut_ptr())
                .is_null(),
            "vpx_img_wrap failed"
        );

        let mut data = Vec::new();
        assert_eq!(
            vpx_codec_encode(
                &mut ectx,
                &img,
                0,
                1,
                VPX_EFLAG_FORCE_KF as vpx_enc_frame_flags_t,
                VPX_DL_GOOD_QUALITY as c_ulong,
            ),
            vpx_codec_err_t_VPX_CODEC_OK
        );
        drain_cx(&mut ectx, &mut data);
        // VP9 may buffer the frame; flush (a null image) until the packet comes out.
        let mut tries = 0;
        while data.is_empty() && tries < 8 {
            vpx_codec_encode(&mut ectx, std::ptr::null(), 0, 1, 0, VPX_DL_GOOD_QUALITY as c_ulong);
            drain_cx(&mut ectx, &mut data);
            tries += 1;
        }
        vpx_codec_destroy(&mut ectx);
        assert!(!data.is_empty(), "encoder produced no packet");

        // ---- decode ----
        let mut dctx: vpx_codec_ctx_t = std::mem::zeroed();
        assert_eq!(
            vpx_codec_dec_init_ver(&mut dctx, dx, std::ptr::null(), 0, VPX_DECODER_ABI_VERSION as c_int),
            vpx_codec_err_t_VPX_CODEC_OK
        );
        assert_eq!(
            vpx_codec_decode(&mut dctx, data.as_ptr(), data.len() as c_uint, std::ptr::null_mut(), 0),
            vpx_codec_err_t_VPX_CODEC_OK
        );
        let mut iter: vpx_codec_iter_t = std::ptr::null();
        let out = vpx_codec_get_frame(&mut dctx, &mut iter);
        assert!(!out.is_null(), "decoder produced no frame");
        let (dw, dh) = ((*out).d_w, (*out).d_h);
        assert_eq!((*out).fmt, vpx_img_fmt_VPX_IMG_FMT_I420, "decoded frame is not I420");
        let luma = *(*out).planes[0];
        vpx_codec_destroy(&mut dctx);
        (dw, dh, luma)
    }

    #[test]
    fn vp9_round_trip() {
        // SAFETY: the static VP9 encoder + decoder interfaces; round_trip tears both down.
        unsafe {
            let (w, h, luma) = round_trip(vpx_codec_vp9_cx(), vpx_codec_vp9_dx());
            assert_eq!((w, h), (16, 16), "decoded VP9 dimensions");
            assert!((80..=176).contains(&luma), "gray luma drifted to {luma} (VP9)");
        }
    }

    #[test]
    fn vp8_round_trip() {
        // SAFETY: the static VP8 encoder + decoder interfaces; round_trip tears both down.
        unsafe {
            let (w, h, luma) = round_trip(vpx_codec_vp8_cx(), vpx_codec_vp8_dx());
            assert_eq!((w, h), (16, 16), "decoded VP8 dimensions");
            assert!((80..=176).contains(&luma), "gray luma drifted to {luma} (VP8)");
        }
    }
}
